        overview=f'''<section class="apartment-overview" id="apartment-details"><div><span class="stay-eyebrow">{t[0]} · IMSFRANE</span><h2>{d['about']}</h2><p>{d['description']}</p><p>{d['sleep']}</p></div><img src="{base}images/apartment/living-room.webp" alt="{t[15][1]}" width="1152" height="1536" loading="lazy"></section>'''
        steps=''.join(f'<article class="apartment-step"><span class="stay-eyebrow">{label}</span><h3>{heading}</h3><p>{body}</p></article>' for label,heading,body in d['steps'])
        programme=f'''<section class="apartment-programme"><span class="stay-eyebrow">IMSFRANE · ATLAS</span><h2>{d['plan']}</h2><p>{d['intro']}</p><div class="apartment-steps">{steps}</div><p class="stay-note">{d['note']}</p></section><section class="apartment-location"><div class="apartment-distance"><strong>10</strong><span>KM · IMSFRANE</span></div><div><h2>{d['where']}</h2><p>{d['whereText']}</p><a class="stay-button" href="https://wa.me/212667772551?text={quote(d['directions']+' — '+t[0])}" target="_blank" rel="noopener">{d['directions']} ↗</a></div></section>'''
        main=re.sub(r'<div class="apartment-intro">.*?<div class="stay-content">',lambda _:overview+'<div class="stay-content">',main,count=1,flags=re.S)
        main=main.replace('<div class="stay-wrap">',hero+'<div class="stay-wrap">',1)
        main=main.replace('<section class="apartment-gallery-section">',programme+'<section class="apartment-gallery-section">')
        main=main.replace('<h2>'+t[11]+'</h2>','<h2>'+d['gallery']+'</h2>')
        s=re.sub(r'<main\b[^>]*>.*?</main>',lambda _:main,s,count=1,flags=re.S)
        s=re.sub(r'<script\b[^>]*src="[^"]*(?:hebergement.min.js|image-controls.js)[^"]*"[^>]*></script>','',s)
        s=re.sub(r'<script\b[^>]*type="application/ld\+json"[^>]*>.*?</script>','',s,flags=re.S)
        s=re.sub(r'<meta\b[^>]*(?:property="og:|name="twitter:|name="description")[^>]*>','',s)
        s=re.sub(r'<title>.*?</title>',f'<title>{t[0]} · {t[3]} | Imsfrane</title>',s,flags=re.S)
        s=s.replace('</head>',f'<link rel="stylesheet" href="{base}apartment-demo.css?v=2"></head>')
        p.write_text(s)
        (root/lang/'hebergement.html').write_text(s)
        chooser=root/lang/'hebergements/index.html'
        chooser.write_text(chooser.read_text().replace(base+'images/bab2.webp',base+'images/apartment/balcony.webp'))
